function genVerbal(d) {
  if (R() < .6) {
    const it = pickBank(AN, 'an', d); const m = mc(it.o);
    return { cat: 'verbal', d, prompt: 'השלם את האנלוגיה. איזו מילה מתאימה במקום סימן השאלה?',
      vis: `<div class="analogy"><span class="w">${it.a}</span><span class="sep">:</span><span class="w">${it.b}</span><span class="like">כמו</span><span class="w">${it.c}</span><span class="sep">:</span><span class="w q">?</span></div>`,
      options: m.options, answer: m.answer, ex: it.ex };
  }
  const it = pickBank(OD, 'od', d); const m = mc(it.o.map(w => /^[\d./%½]+$/.test(w) ? L(w) : w));
  return { cat: 'verbal', d, prompt: 'איזה פריט לא שייך לקבוצה?', vis: '', options: m.options, answer: m.answer, ex: it.ex };
}
